import{_ as s,C as c,o,c as u,a2 as t,b as r,w as a,a as d,E as l,a3 as n}from"./chunks/framework.CgxQ0r6v.js";const E=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 3","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_II/documentacion/II-V/Lectura_Catedra_Evaluacion_3.md","filePath":"materias/Proyecto_Sociotecnologico_II/documentacion/II-V/Lectura_Catedra_Evaluacion_3.md"}'),m={name:"materias/Proyecto_Sociotecnologico_II/documentacion/II-V/Lectura_Catedra_Evaluacion_3.md"};function p(b,e,f,h,g,C){const i=c("Mermaid");return o(),u("div",null,[e[2]||(e[2]=t('<h1 id="manual-de-estudio-profundo-evaluacion-3" tabindex="-1">Manual de Estudio Profundo: Evaluación 3 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-3" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 3&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-ii-trayecto-ii-trimestre-v" tabindex="-1">Materia: Proyecto Sociotecnológico II (Trayecto II - Trimestre V) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-ii-trayecto-ii-trimestre-v" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico II (Trayecto II - Trimestre V)&quot;">​</a></h2><h3 id="eje-tematico-diseno-de-arquitectura-y-base-de-datos-relacional" tabindex="-1">Eje Temático: Diseño de Arquitectura y Base de Datos Relacional <a class="header-anchor" href="#eje-tematico-diseno-de-arquitectura-y-base-de-datos-relacional" aria-label="Permalink to &quot;Eje Temático: Diseño de Arquitectura y Base de Datos Relacional&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-memoria-y-la-estructura-del-software" tabindex="-1">🧭 Introducción: La Memoria y la Estructura del Software <a class="header-anchor" href="#🧭-introduccion-la-memoria-y-la-estructura-del-software" aria-label="Permalink to &quot;🧭 Introducción: La Memoria y la Estructura del Software&quot;">​</a></h2><p>Una aplicación informática bien diseñada se sostiene sobre dos pilares fundamentales:</p><ol><li><strong>La Arquitectura de Software:</strong> La organización de los componentes que garantiza que el sistema sea modular, seguro y fácil de mantener.</li><li><strong>La Base de Datos Relacional:</strong> El motor que garantiza que la información se guarde de forma consistente, sin redundancias, con integridad y protegida contra pérdidas.</li></ol><p>En el PST II, los proyectos deben abandonar el almacenamiento rudimentario en archivos de texto o planillas de cálculo, migrando formalmente a <strong>Sistemas Gestores de Bases de Datos Relacionales (SGBD) Libres</strong> como PostgreSQL, MariaDB o SQLite.</p><hr><h2 id="🏛️-capitulo-i-del-modelo-entidad-relacion-mer-al-modelo-relacional-mr" tabindex="-1">🏛️ CAPÍTULO I: Del Modelo Entidad-Relación (MER) al Modelo Relacional (MR) <a class="header-anchor" href="#🏛️-capitulo-i-del-modelo-entidad-relacion-mer-al-modelo-relacional-mr" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: Del Modelo Entidad-Relación (MER) al Modelo Relacional (MR)&quot;">​</a></h2><p>El modelado de datos pasa por dos etapas de abstracción:</p>',11)),(o(),r(n,null,{default:a(()=>[l(i,{id:"mermaid-38",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5B%22%F0%9F%A7%A0%20Realidad%20Comunitaria%20(Papeles%2C%20Fichas)%22%5D%20--%3E%20B%5B%22%F0%9F%93%90%20Modelo%20Entidad-Relaci%C3%B3n%20(MER%20Conceptual)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%F0%9F%97%84%EF%B8%8F%20Modelo%20Relacional%20(MR%20F%C3%ADsico%20%2F%20Tablas)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%F0%9F%92%BE%20C%C3%B3digo%20SQL%20(DDL%20en%20SGBD%20Libre)%22%5D%0A%0A%20%20%20%20style%20A%20fill%3A%231e293b%2Cstroke%3A%2364748b%2Ccolor%3A%23fff%0A%20%20%20%20style%20B%20fill%3A%230f766e%2Cstroke%3A%2314b8a6%2Ccolor%3A%23fff%0A%20%20%20%20style%20C%20fill%3A%230369a1%2Cstroke%3A%230ea5e9%2Ccolor%3A%23fff%0A%20%20%20%20style%20D%20fill%3A%234338ca%2Cstroke%3A%236366f1%2Ccolor%3A%23fff%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t('<h3 id="_1-1-conceptos-del-mer-modelo-conceptual-de-peter-chen" tabindex="-1">1.1 Conceptos del MER (Modelo Conceptual de Peter Chen) <a class="header-anchor" href="#_1-1-conceptos-del-mer-modelo-conceptual-de-peter-chen" aria-label="Permalink to &quot;1.1 Conceptos del MER (Modelo Conceptual de Peter Chen)&quot;">​</a></h3><ul><li><strong>Entidad (Rectángulo):</strong> Objeto o concepto del mundo real sobre el cual se recolecta información (ej: <code>Habitante</code>, <code>Familia</code>, <code>Beneficio</code>, <code>Medicamento</code>).</li><li><strong>Atributos (Óvalos):</strong> Propiedades o características que describen a la entidad (ej: <code>cedula</code>, <code>nombre</code>, <code>direccion</code>). <ul><li><em>Atributo Clave / Identificador Único:</em> Atributo cuyo valor no se repite entre instancias de la entidad (ej: <code>cedula</code> o <code>id_habitante</code>).</li></ul></li><li><strong>Relaciones (Rombos):</strong> Asociaciones entre dos o más entidades (ej: <code>Habitante</code> <em>pertenece a</em> <code>Familia</code>).</li><li><strong>Cardinalidad:</strong> Número de instancias asociadas: <ul><li>Uno a Uno (1:1)</li><li>Uno a Muchos (1:N)</li><li>Muchos a Muchos (N:M) <em>(requiere tabla intermedia en el paso a relacional)</em>.</li></ul></li></ul><hr><h2 id="🧩-capitulo-ii-normalizacion-de-bases-de-datos" tabindex="-1">🧩 CAPÍTULO II: Normalización de Bases de Datos <a class="header-anchor" href="#🧩-capitulo-ii-normalizacion-de-bases-de-datos" aria-label="Permalink to &quot;🧩 CAPÍTULO II: Normalización de Bases de Datos&quot;">​</a></h2><p>La <strong>normalización</strong> es una técnica formal de diseño que organiza las tablas para eliminar la redundancia de datos y prevenir anomalías de inserción, actualización y borrado.</p><h3 id="_2-1-primera-forma-normal-1fn" tabindex="-1">2.1 Primera Forma Normal (1FN) <a class="header-anchor" href="#_2-1-primera-forma-normal-1fn" aria-label="Permalink to &quot;2.1 Primera Forma Normal (1FN)&quot;">​</a></h3><ul><li>Todos los atributos deben contener <strong>valores atómicos</strong> (indivisibles).</li><li>No deben existir grupos repetitivos ni columnas multivaluadas (ej: no tener una columna <code>telefonos</code> con varios números separados por comas).</li><li>Cada tabla debe tener una <strong>Clave Primaria (PK)</strong> definida.</li></ul><h3 id="_2-2-segunda-forma-normal-2fn" tabindex="-1">2.2 Segunda Forma Normal (2FN) <a class="header-anchor" href="#_2-2-segunda-forma-normal-2fn" aria-label="Permalink to &quot;2.2 Segunda Forma Normal (2FN)&quot;">​</a></h3><ul><li>Debe estar en 1FN.</li><li>Todos los atributos que no forman parte de la clave primaria deben depender funcionalmente de <strong>toda la clave primaria</strong>, no de una parte de ella (aplica en claves primarias compuestas).</li></ul><h3 id="_2-3-tercera-forma-normal-3fn" tabindex="-1">2.3 Tercera Forma Normal (3FN) <a class="header-anchor" href="#_2-3-tercera-forma-normal-3fn" aria-label="Permalink to &quot;2.3 Tercera Forma Normal (3FN)&quot;">​</a></h3><ul><li>Debe estar en 2FN.</li><li>No deben existir <strong>dependencias transitivas</strong>: ningún atributo no clave debe depender de otro atributo no clave.</li><li><em>Ejemplo de anomalía:</em> En una tabla <code>habitantes</code>, guardar <code>codigo_parroquia</code> y <code>nombre_parroquia</code>. Si cambia el nombre de la parroquia, habría que modificarlo en miles de filas. La solución es separar <code>parroquias</code> en su propia tabla con su propio identificador.</li></ul><hr><h2 id="📑-capitulo-iii-diccionario-de-datos-y-restricciones-de-integridad" tabindex="-1">📑 CAPÍTULO III: Diccionario de Datos y Restricciones de Integridad <a class="header-anchor" href="#📑-capitulo-iii-diccionario-de-datos-y-restricciones-de-integridad" aria-label="Permalink to &quot;📑 CAPÍTULO III: Diccionario de Datos y Restricciones de Integridad&quot;">​</a></h2><p>El <strong>Diccionario de Datos</strong> es la documentación técnica formal que describe la estructura interna de cada tabla de la base de datos:</p><h3 id="ejemplo-de-ficha-de-diccionario-de-datos-tabla-habitantes" tabindex="-1">Ejemplo de Ficha de Diccionario de Datos: Tabla <code>habitantes</code> <a class="header-anchor" href="#ejemplo-de-ficha-de-diccionario-de-datos-tabla-habitantes" aria-label="Permalink to &quot;Ejemplo de Ficha de Diccionario de Datos: Tabla `habitantes`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Columna</th><th>Tipo de Dato</th><th>Longitud</th><th>Permite Nulos</th><th>Clave</th><th>Restricciones / Validación</th><th>Descripción</th></tr></thead><tbody><tr><td><code>id_habitante</code></td><td><code>SERIAL / INT</code></td><td>4 bytes</td><td>NO</td><td><strong>PK</strong></td><td>Auto-incremental</td><td>Identificador interno único</td></tr><tr><td><code>cedula</code></td><td><code>VARCHAR</code></td><td>12</td><td>NO</td><td><strong>UNIQUE</strong></td><td>Formato: <code>V-12345678</code></td><td>Cédula de identidad del ciudadano</td></tr><tr><td><code>nombres</code></td><td><code>VARCHAR</code></td><td>80</td><td>NO</td><td>-</td><td>Solo caracteres alfabéticos</td><td>Nombres del habitante</td></tr><tr><td><code>apellidos</code></td><td><code>VARCHAR</code></td><td>80</td><td>NO</td><td>-</td><td>Solo caracteres alfabéticos</td><td>Apellidos del habitante</td></tr><tr><td><code>id_familia</code></td><td><code>INT</code></td><td>4 bytes</td><td>SÍ</td><td><strong>FK</strong></td><td>Referencia a <code>familias(id)</code></td><td>Familia a la que pertenece</td></tr><tr><td><code>activo</code></td><td><code>BOOLEAN</code></td><td>1 byte</td><td>NO</td><td>-</td><td><code>DEFAULT true</code></td><td>Estado en el censo comunitario</td></tr></tbody></table><hr><h2 id="🏗️-capitulo-iv-arquitectura-de-software-el-patron-mvc" tabindex="-1">🏗️ CAPÍTULO IV: Arquitectura de Software: El Patrón MVC <a class="header-anchor" href="#🏗️-capitulo-iv-arquitectura-de-software-el-patron-mvc" aria-label="Permalink to &quot;🏗️ CAPÍTULO IV: Arquitectura de Software: El Patrón MVC&quot;">​</a></h2><p>Para garantizar que el código sea limpio, desacoplado y fácil de mantener por futuros estudiantes o por la comunidad, se adopta el patrón de diseño arquitectónico <strong>Modelo-Vista-Controlador (MVC)</strong>:</p>',19)),(o(),r(n,null,{default:a(()=>[l(i,{id:"mermaid-334",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20User((%22%F0%9F%91%A4%20Usuario%22))%20%3C--%3E%7CInteract%C3%BAa%7C%20View%5B%22%F0%9F%96%A5%EF%B8%8F%20VISTA%20(UI)%3Cbr%3EHTML5%20%2F%20CSS%20%2F%20Blade%20%2F%20EJS%22%5D%0A%20%20%20%20View%20--%3E%7CEnv%C3%ADa%20Peticiones%20HTTP%7C%20Controller%5B%22%E2%9A%99%EF%B8%8F%20CONTROLADOR%3Cbr%3EL%C3%B3gica%20de%20Negocio%20y%20Ruteo%22%5D%0A%20%20%20%20Controller%20--%3E%7CSolicita%20%2F%20Actualiza%20Datos%7C%20Model%5B%22%F0%9F%97%84%EF%B8%8F%20MODELO%3Cbr%3EReglas%20de%20Datos%20y%20Consultas%20SQL%22%5D%0A%20%20%20%20Model%20--%3E%7CInteract%C3%BAa%7C%20DB%5B(%22%F0%9F%92%BE%20Base%20de%20Datos%3Cbr%3EPostgreSQL%20%2F%20MariaDB%22)%5D%0A%20%20%20%20Model%20--%3E%7CRetorna%20Datos%7C%20Controller%0A%20%20%20%20Controller%20--%3E%7CPasa%20Datos%20Formateados%7C%20View%0A%0A%20%20%20%20style%20User%20fill%3A%231e293b%2Cstroke%3A%2364748b%2Ccolor%3A%23fff%0A%20%20%20%20style%20View%20fill%3A%230f766e%2Cstroke%3A%2314b8a6%2Ccolor%3A%23fff%0A%20%20%20%20style%20Controller%20fill%3A%231e3a8a%2Cstroke%3A%233b82f6%2Ccolor%3A%23fff%0A%20%20%20%20style%20Model%20fill%3A%237c2d12%2Cstroke%3A%23ea580c%2Ccolor%3A%23fff%0A%20%20%20%20style%20DB%20fill%3A%234338ca%2Cstroke%3A%236366f1%2Ccolor%3A%23fff%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[d(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=t('<h3 id="_4-1-separacion-de-responsabilidades" tabindex="-1">4.1 Separación de Responsabilidades <a class="header-anchor" href="#_4-1-separacion-de-responsabilidades" aria-label="Permalink to &quot;4.1 Separación de Responsabilidades&quot;">​</a></h3><ul><li><strong>Modelo:</strong> Encapsula el acceso y manipulación de los datos. No sabe nada de HTML ni de interfaces gráficas.</li><li><strong>Vista:</strong> Es la pantalla visible para el usuario (formularios, tablas, botones, modales). No ejecuta consultas SQL directas.</li><li><strong>Controlador:</strong> Es el intermediario. Recibe la acción del usuario desde la vista, aplica validaciones y lógica de negocio, solicita los datos al modelo y decide qué vista mostrar de vuelta al usuario.</li></ul><hr><h2 id="🎨-capitulo-v-diseno-de-interfaces-de-usuario-wireframes-y-ui-ux" tabindex="-1">🎨 CAPÍTULO V: Diseño de Interfaces de Usuario (Wireframes y UI/UX) <a class="header-anchor" href="#🎨-capitulo-v-diseno-de-interfaces-de-usuario-wireframes-y-ui-ux" aria-label="Permalink to &quot;🎨 CAPÍTULO V: Diseño de Interfaces de Usuario (Wireframes y UI/UX)&quot;">​</a></h2><p>Antes de programar en HTML/CSS, los estudiantes deben elaborar los <strong>bocetos o esquemas visuales (wireframes)</strong> de las pantallas principales del sistema:</p><ol><li><strong>Pantalla de Inicio de Sesión (Login):</strong> Con validaciones visuales y recuperación de acceso.</li><li><strong>Panel Principal (Dashboard):</strong> Con accesos directos a los módulos según el rol del usuario (Administrador vs. Operador).</li><li><strong>Formularios de Registro y Edición:</strong> Con etiquetas claras, botones visibles y mensajes de error amigables.</li><li><strong>Módulos de Consulta y Tablas de Datos:</strong> Con paginación, filtros de búsqueda rápida y botones de exportación a PDF.</li></ol><hr><h2 id="📝-conclusiones-y-entregables-de-la-evaluacion-3" tabindex="-1">📝 Conclusiones y Entregables de la Evaluación 3 <a class="header-anchor" href="#📝-conclusiones-y-entregables-de-la-evaluacion-3" aria-label="Permalink to &quot;📝 Conclusiones y Entregables de la Evaluación 3&quot;">​</a></h2><p>Para la Evaluación 3 del Trimestre V, el equipo presentará:</p><ol><li><strong>Diagrama de Entidad-Relación (MER)</strong> y <strong>Diagrama Relacional (MR)</strong> con justificación de la 3FN.</li><li><strong>Diccionario de Datos Completo</strong> de todas las tablas del sistema.</li><li><strong>Script SQL de Creación (DDL)</strong> con claves primarias, foráneas y restricciones de integridad.</li><li><strong>Wireframes y Mapa de Navegación</strong> de la interfaz gráfica de usuario.</li></ol>',10))])}const _=s(m,[["render",p]]);export{E as __pageData,_ as default};
